+
+  final listings = <String, List<RemoteFileEntry>>{};
+  final listCalls = <String>[];
+  int closeCalls = 0;
+  Completer<void>? holdNext;
+
+  @override
+  Future<List<RemoteFileEntry>> listDirectory(String path) async {
+    listCalls.add(path);
+    final hold = holdNext;
+    if (hold != null) {
+      holdNext = null;
+      await hold.future;
+    }
+    final entries = listings[path];
+    if (entries == null) {
